import session from 'express-session';

app.use(session({
  name: '__Host-sid', // Not 'express.sid' or 'connect.sid'
  secret: process.env.SESSION_SECRET,
  cookie: { httpOnly: true, secure: true, sameSite: 'lax', path: '/' },
}));

res.cookie('__Host-session', token, {
  httpOnly: true,
  secure: true,
  sameSite: 'lax',
  path: '/',
});

// Client reads CSRF token from cookie (not HttpOnly)
const csrfToken = document.cookie.match(/csrf-token=([^;]+)/)?.[1];

fetch('/api/transfer', {
  method: 'POST',
  headers: { 'X-CSRF-Token': csrfToken },
  body: JSON.stringify({ amount: 100 }),
});

const maxAgeSeconds = 3600;
const expires = new Date(Date.now() + maxAgeSeconds * 1000).toUTCString();
res.setHeader('Set-Cookie', `session=abc123; Max-Age=${maxAgeSeconds}; Expires=${expires}; Secure; HttpOnly`);
